pub fn contact_manifolds(
    collider1: &Collider,
    position1: impl Into<Position>,
    rotation1: impl Into<Rotation>,
    collider2: &Collider,
    position2: impl Into<Position>,
    rotation2: impl Into<Rotation>,
    prediction_distance: Scalar,
    manifolds: &mut Vec<ContactManifold>,
) {
    let position1: Position = position1.into();
    let position2: Position = position2.into();
    let rotation1: Rotation = rotation1.into();
    let rotation2: Rotation = rotation2.into();
    let isometry1 = make_pose(position1, rotation1);
    let isometry2 = make_pose(position2, rotation2);
    let isometry12 = isometry1.inv_mul(&isometry2);

    // TODO: Reuse manifolds from previous frame to improve performance
    let mut new_manifolds =
        Vec::<parry::query::ContactManifold<(), ()>>::with_capacity(manifolds.len());
    let result = parry::query::DefaultQueryDispatcher.contact_manifolds(
        &isometry12,
        collider1.shape_scaled().0.as_ref(),
        collider2.shape_scaled().0.as_ref(),
        prediction_distance,
        &mut new_manifolds,
        &mut None,

manifolds.extend(new_manifolds.iter().filter_map(|manifold| {
    // Skip empty manifolds.
    if manifold.contacts().is_empty() {
        return None;
    }

    let subpos1 = manifold.subshape_pos1.unwrap_or_default();
    let local_normal: Vector = (subpos1.rotation * manifold.local_n1).normalize();
    let normal = rotation1 * local_normal;

    // Make sure the normal is valid
    if !normal.is_normalized() {
        return None;
    }

    let points = manifold.contacts().iter().map(|contact| {
        // The contact point is the midpoint of the two points in world space.
        // The anchors are relative to the positions of the colliders.
        let point1 = rotation1 * subpos1.transform_point(contact.local_p1);
        let anchor1 = point1 + normal * contact.dist * 0.5;
        let anchor2 = anchor1 + (position1.0 - position2.0);
        let world_point = position1.0 + anchor1;
        ContactPoint::new(anchor1, anchor2, world_point, -contact.dist)
            .with_feature_ids(contact.fid1.into(), contact.fid2.into())
    });

    let manifold = ContactManifold::new(points, normal);

    Some(manifold)
}));

// Compute the contact manifolds using the effective speculative margin.
let context = ContactManifoldContext::new(
    collider1.entity,
    collider2.entity,
    collider_context,
);
collider1.shape.contact_manifolds_with_context(
    collider2.shape,
    collider1.position.0,
    *collider1.rotation,
    collider2.position.0,
    *collider2.rotation,
    max_contact_distance,
    &mut contacts.manifolds,
    context,
);

// Transform and prune contact data.
contacts.manifolds.retain_mut(|manifold| {
    // Set the initial surface properties.
    manifold.friction = friction;
    manifold.restitution = restitution;
    #[cfg(feature = "2d")]
    {
        manifold.tangent_speed = 0.0;
    }
    #[cfg(feature = "3d")]
    {
        manifold.tangent_velocity = Vector::ZERO;
    }

    let normal = manifold.normal;

    // Transform and prune contact points.
    manifold.retain_points_mut(|point| {
        // Transform contact points to be relative to the centers of mass of the bodies.
        point.anchor1 = point.anchor1 + collider_offset1 - world_com1;
        point.anchor2 = point.anchor2 + collider_offset2 - world_com2;

        // Add the collision margin to the penetration depth.
        point.penetration += collision_margin_sum;

        // Compute the relative velocity along the contact normal.
        #[cfg(feature = "2d")]
        let relative_velocity = relative_linear_velocity
            + ang_vel2 * point.anchor2.perp()
            - ang_vel1 * point.anchor1.perp();
        #[cfg(feature = "3d")]
        let relative_velocity = relative_linear_velocity
            + ang_vel2.cross(point.anchor2)
            - ang_vel1.cross(point.anchor1);
        let normal_speed = relative_velocity.dot(normal);
        point.normal_speed = normal_speed;

        // Keep the contact if (1) the separation distance is below the required threshold,
        // or if (2) the bodies are expected to come into contact within the next time step.
        -point.penetration < effective_speculative_margin || {
            let delta_distance = normal_speed * delta_secs;
            delta_distance - point.penetration < effective_speculative_margin
        }
    });

    // Prune extra contact points.
    #[cfg(feature = "3d")]
    if manifold.points.len() > 4 {
        manifold.prune_points();
    }

    !manifold.points.is_empty()
});

// Check if the colliders are now touching.
let mut touching = !contacts.manifolds.is_empty();

if touching && contacts.flags.contains(ContactPairFlags::MODIFY_CONTACTS) {
    par_commands.command_scope(|mut commands| {

let mut old_manifolds = core::mem::take(manifolds);

let mut leaf1_fn = |leaf1: u32| {
    composite1.map_part_at(leaf1, &mut |part_pos1, part_shape1, normal_constraints1| {
        let sub_detector = match workspace.sub_detectors.entry(leaf1) {
            Entry::Occupied(entry) => {
                let sub_detector = entry.into_mut();
                let manifold = old_manifolds[sub_detector.manifold_id].take();
                sub_detector.manifold_id = manifolds.len();
                sub_detector.timestamp = new_timestamp;
                manifolds.push(manifold);
                sub_detector
            }
            Entry::Vacant(entry) => {
                let sub_detector = SubDetector {
                    manifold_id: manifolds.len(),
                    timestamp: new_timestamp,
                };

                let mut manifold = ContactManifold::new();

                if flipped {
                    manifold.subshape1 = 0;
                    manifold.subshape2 = leaf1;
                    manifold.subshape_pos2 = part_pos1.copied();
                } else {
                    manifold.subshape1 = leaf1;
                    manifold.subshape2 = 0;
                    manifold.subshape_pos1 = part_pos1.copied();
                };

                manifolds.push(manifold);
                entry.insert(sub_detector)
            }
        };

        let manifold = &mut manifolds[sub_detector.manifold_id];

        if flipped {
            let _ = dispatcher.contact_manifold_convex_convex(
                &part_pos1.prepend_to(&pos21),
                shape2,
                part_shape1,
                None,
                normal_constraints1,
                prediction,
                manifold,

// TODO: don't redispatch at each frame (we should probably do the same as
// the heightfield).
for (i, triangle_id) in new_interferences.iter().enumerate() {
    if *triangle_id >= trimesh1.num_triangles() as u32 {
        // Because of SIMD padding, the broad-phase may return triangle indices greater
        // than the max.
        continue;
    }

    if !same_local_aabb2 {
        loop {
            match old_inter_it.peek() {
                Some(old_triangle_id) if *old_triangle_id < *triangle_id => {
                    let _ = old_inter_it.next();
                    let _ = old_manifolds_it.next();
                }
                _ => break,
            }
        }

        let manifold = if old_inter_it.peek() != Some(triangle_id) {
            let (id1, id2) = if flipped {
                (0, *triangle_id)
            } else {
                (*triangle_id, 0)
            };
            ContactManifold::with_data(id1, id2, ManifoldData::default())
        } else {
            // We already have a manifold for this triangle.
            let _ = old_inter_it.next();
            old_manifolds_it.next().unwrap()
        };

        manifolds.push(manifold);
    }

    let manifold = &mut manifolds[i];
    let triangle1 = trimesh1.triangle(*triangle_id);
    let triangle_normals1 = trimesh1.triangle_normal_constraints(*triangle_id);
    let normal_constraints1 = triangle_normals1
        .as_ref()
        .map(|proj| proj as &dyn NormalConstraints);

pub struct ContactManifold<ManifoldData, ContactData> {
    // NOTE: use a SmallVec instead?
    // And for 2D use an ArrayVec since there will never be more than 2 contacts anyways.
    /// The contacts points.
    #[cfg(feature = "dim2")]
    pub points: arrayvec::ArrayVec<TrackedContact<ContactData>, 2>,
    /// The contacts points.
    #[cfg(feature = "dim3")]
    pub points: Vec<TrackedContact<ContactData>>,
    /// The contact normal of all the contacts of this manifold, expressed in the local space of the first shape.
    pub local_n1: Vector,
    /// The contact normal of all the contacts of this manifold, expressed in the local space of the second shape.
    pub local_n2: Vector,
    /// The first subshape involved in this contact manifold.
    ///
    /// This is zero if the first shape is not a composite shape.
    pub subshape1: u32,
    /// The second subshape involved in this contact manifold.
    ///
    /// This is zero if the second shape is not a composite shape.
    pub subshape2: u32,
    /// If the first shape involved is a composite shape, this contains the position of its subshape
    /// involved in this contact.
    pub subshape_pos1: Option<Pose>,
    /// If the second shape involved is a composite shape, this contains the position of its subshape
    /// involved in this contact.
    pub subshape_pos2: Option<Pose>,
